INSERT INTO `user_member` VALUES (1,'Shanjida Hride','01745449111','shanjidahride8@gmail.com','shanjidahride8@gmail.com',NULL,'1111222233','','',NULL,NULL,NULL,'Dhaka','Barishal','1993-07-07','SQA','Female','Married','Islam','','',1,1,1,1,0,NULL,'2025-08-11 23:47:32.084966',NULL,1,1,1),(41,'Test User','01777048151','birdlove629@gmail.com','birdlove629@gmail.com',NULL,'7894563210','members/41_Test User/christopher-campbell-rDEOVtE7vOs-unsplash.jpg','members/41_Test User/low_quality_christopher-campbell-rDEOVtE7vOs-unsplash.jpg','Shanjida Hride is a dedicated resident of Bashundhara Residential Area, living in Tower A, since 2023. With a background in software quality assurance, she actively contributes to the community’s tech initiatives, helping neighbors troubleshoot internet and smart‑home issues. Outside of work, Shanjida enjoys organizing weekend clean‑up drives and teaching coding basics to local schoolchildren. Her friendly demeanor and willingness to lend a hand have made her a well‑loved member of the Estate Link community.','Shanjida Hride is a dedicated resident of Bashundhara Residential Area, living in Tower A, Unit 4B since 2023. With a background in software quality assurance, she actively contributes to the community’s tech initiatives, helping neighbors troubleshoot internet and smart‑home issues. Outside of work, Shanjida enjoys organizing weekend clean‑up drives and teaching coding basics to local schoolchildren. Her friendly demeanor and willingness to lend a hand have made her a well‑loved member of the Estate Link community.','Shanjida Hride is a dedicated resident of Bashundhara Residential Area, living in Tower A, Unit 4B since 2023. With a background in software quality assurance, she actively contributes to the community’s tech initiatives, helping neighbors troubleshoot internet and smart‑home issues. Outside of work, Shanjida enjoys organizing weekend clean‑up drives and teaching coding basics to local schoolchildren. Her friendly demeanor and willingness to lend a hand have made her a well‑loved member of the Estate Link community.','House # 419 (4th Floor), Flat B2 Road 12/B, Block E Bashundhara Residential Area Badda Thana, Dhaka‑1229 Dhaka Division, Bangladesh','House # 419 (4th Floor), Flat B2 Road 12/B, Block E Bashundhara Residential Area Badda Thana, D','2025-04-30','SQA','Male','Married','Judaism','members/41_Bird Love/Screenshot_2024-08-12_204322.png','members/41_Bird Love/leave_DTG.jpg',1,1,1,1,0,'2025-05-19 11:31:26.947718','2025-08-02 17:40:06.687738',1,1,20,1),(451,'Staff 1','01777856545','staff1@gmail.com',NULL,NULL,NULL,'members/451_Staff 1/christopher-campbell-rDEOVtE7vOs-unsplash.jpg','members/451_Staff 1/low_quality_christopher-campbell-rDEOVtE7vOs-unsplash.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',1,1,1,1,1,'2025-07-30 14:07:19.064155','2025-07-30 20:05:57.237177',1,1,308,2),(452,'Hride QA  (Manager)','01777854575','hride.qa@gmail.com','hride.qa@gmail.com',NULL,'1111222252','members/452_Hride QA  (Manager)/Shanjida_Hride.jpg','members/452_Hride QA  (Manager)/low_quality_Shanjida_Hride.jpg','Hride QA  (Manager)','https://www.facebook.com/sirina.jahana.175330/','https://www.linkedin.com/in/shanjida-hride-b38222173/','Dhaka','Patuakhali','1999-02-02','SQA','Female','Married','Islam','members/452_Hride QA  (Manager)/andrei-castanha-iwRUc0ESLsw-unsplash_-_Copy_-_Copy_-_Copy.jpg','members/452_Hride QA  (Manager)/scott-szarapka-y07ClgzcVmc-unsplash_-_Copy.jpg',1,1,1,1,0,'2025-07-30 14:17:53.732293','2025-08-02 17:37:11.594405',1,1,306,1),(453,'Tanvir Islam','01777854525','islam@gmail.com',NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',0,0,1,0,1,'2025-07-30 14:42:32.136532','2025-07-30 15:44:31.708580',1,1,NULL,1),(454,'Shanta Properties','01777854525','sumiakte1995@gmail.com','sumiakte1995@gmail.com',NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',0,1,0,1,1,'2025-07-30 16:03:14.767914','2025-08-07 15:52:45.257205',1